"""This file was partially generated by LLM"""

import json
import os
import re
import sys
import time
import unicodedata

import requests

# the console is cp1252 on Windows; song/artist names are not
sys.stdout.reconfigure(encoding="utf-8", errors="replace")

API_URL = "https://lrclib.net/api/search"

session = requests.Session()
session.headers.update({"User-Agent": "eurovision-lyrics-scraper/1.0"})


ARTIST_NOISE = {"and", "feat", "ft", "the", "with", "of"}


def normalize(text):
    """Lowercase, strip accents and punctuation, so 'Tu Canción' == 'Tu cancion'."""
    text = unicodedata.normalize("NFKD", text or "")
    text = "".join(c for c in text if not unicodedata.combining(c))
    return re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()


def is_same_song(match, song_title, artist_name):
    """A title-only search returns anything, so verify the hit before trusting it."""
    if normalize(match.get("trackName")) != normalize(song_title):
        return False

    # artist strings differ across sources ('X and Y' vs 'X feat. Y'), so
    # accept the match if any meaningful name token is shared
    wanted = {t for t in normalize(artist_name).split() if len(t) > 2} - ARTIST_NOISE
    found = set(normalize(match.get("artistName")).split())
    return bool(wanted & found)


def search(params, retries=5):
    """GET the search endpoint, riding out the API's intermittent 503s."""
    for attempt in range(retries):
        try:
            response = session.get(API_URL, params=params, timeout=30)
        except requests.RequestException as exc:
            print(f"  request failed ({exc}), retrying...")
            time.sleep(2 ** attempt)
            continue

        # 503/429 mean the server is busy - back off and try again
        if response.status_code in (429, 503):
            wait = 2 ** attempt
            print(f"  {response.status_code} from API, retrying in {wait}s...")
            time.sleep(wait)
            continue

        if response.status_code != 200:
            print(f"Error fetching lyrics: {response.status_code}")
            return []

        return response.json()

    print(f"  giving up on {params} after {retries} attempts")
    return []


def fetch_lyrics(song_title, artist_name):
    # The API returns a list of matches; grab the first one that has lyrics
    for match in search({"track_name": song_title, "artist_name": artist_name}):
        if match.get("plainLyrics"):
            return match["plainLyrics"]

    # The artist string in the dataset often does not match the one lrclib
    # stores, so fall back to a title-only search and verify the hit ourselves
    for match in search({"q": song_title}):
        if match.get("plainLyrics") and is_same_song(match, song_title, artist_name):
            return match["plainLyrics"]

    return None

if __name__ == "__main__":
    with open("dataset_info.json", 'r', encoding='utf-8') as file:
        dataset_info = json.load(file)

    year_path_lst = []
    for year, year_data in dataset_info.items():
        year_path_lst.append((year, year_data["path"]))

    os.makedirs(os.path.join("raw", "lyrics"), exist_ok=True)

    for year, path in year_path_lst:
        print(f"Processing {year}")

        with open(path, 'r', encoding='utf-8') as file:
            year_data = json.load(file)

        for country, entry in year_data.items():
            song_title = entry.get("song")
            artist_name = entry.get("artist")

            if not (song_title and artist_name):
                continue

            out_path = os.path.join("raw", "lyrics", f"{country.replace(' ', '_')}_{year}.txt")
            if os.path.exists(out_path):
                continue

            lyrics = fetch_lyrics(song_title, artist_name)
            if lyrics is None:
                print(f"  no lyrics found for {country} {year}: {artist_name} - {song_title}")
                continue

            with open(out_path, 'w', encoding='utf-8') as file:
                file.write(lyrics)

            time.sleep(0.5)
